import base64
import os

IMAGES = {
    "room1.png": "",
    "room2.png": "",
    "room3.png": "",
    "room4.png": "",
    "boss1.png": "",
    "boss2.png": "",
    "hard1.png": "",
    "hard2.png": "",
    "hard3.png": "",
    "hard4.png": ""
}


def main():
    out_dir = os.path.join(os.path.dirname(__file__), '..', 'static', 'maze')
    os.makedirs(out_dir, exist_ok=True)
    for fname, b64 in IMAGES.items():
        path = os.path.join(out_dir, fname)
        with open(path, 'wb') as f:
            f.write(base64.b64decode(b64))
    print('Wrote placeholder images to:', out_dir)

if __name__ == '__main__':
    main()
